{
  "narrative_summary": "This result rests on the link from Engineering Capacity to Total Cost of Ownership. If capacity assumptions change, more runs could support a different option. In this model, 58% of runs supported Rebuild In House.",
  "story_headlines": {
    "opt_rebuild": "Rebuild In House reflects lower modelled cost of ownership when engineering capacity holds up as assumed.",
    "opt_extend": "Extend Vendor Contract would gain support if engineering capacity proves more constrained than currently assumed."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 61% of variations, based on current estimates.",
    "primary_risk": "The link from Engineering Capacity to Total Cost of Ownership is not firmly evidenced and could shift the comparison.",
