    "fac_eng_capacity": {
      "specific_action": "Run a capacity audit against current engineering roadmap commitments to establish actual available headcount for a rebuild.",
      "rationale": "This factor is asserted rather than evidenced, and the comparison is sensitive to it.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the answer before looking at the audit data."
    },
    "fac_vendor_price": {
      "specific_action": "Request the vendor's multi-year price schedule and any contractual escalation clauses in writing.",
      "rationale": "Vendor Price Path carries only moderate confidence and feeds the cost outcome directly.",
      "evidence_type": "market_research",
      "decision_hygiene": "Compare the quoted schedule against your own extrapolation before reacting to it."
    }
  },
  "scenario_contexts": {
    "edge_capacity_tco": {
      "trigger_description": "If Engineering Capacity proves tighter than assumed in its link to Total Cost of Ownership...",
      "consequence": "...then the most runs would support Extend Vendor Contract rather than Rebuild In House."
    }
  },
