    },
    {
      "question": "Who will argue that Engineering Capacity matters less than this model treats it?",
      "principle": "Structured dissent",
      "applies_because": "A critique flags that engineering capacity is asserted rather than evidenced, so deliberately surfacing disagreement on it is warranted."
    }
  ],
